#!/usr/bin/env bash
# Reference solution, applied only by `astrona test` (the `testing:` block).
# `astrona run` never runs this. Taken from solution.md - if one changes,
# change the other.
set -euo pipefail

in_runner() { kubectl -n dac exec -i deploy/dac-runner -- sh -s; }
in_runner <<'GRADE'
set -u
. /opt/dac/grader-lib.sh
repo_change "Add the team overview dashboard" "mkdir -p dashboards/cue && printf '%s' '' | base64 -d > dashboards/cue/team-overview.cue"
dac-run sh -c 'percli dac build -f dashboards/cue/team-overview.cue -ojson && percli apply -f built/dashboards/cue/team-overview_output.json'
GRADE
